/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, effect, inject, untracked } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatBadgeModule } from '@angular/material/badge';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslocoPipe } from '@jsverse/transloco';
import { OfflineQueueService } from '@shared/data/offline/offline-queue.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { OfflineSyncDialogComponent } from './offline-sync-dialog.component';

/** Intervalo mínimo entre avisos de conexión recuperada. */
const NOTIFY_EVERY = 5 * 60_000;

/**
 * Indicador de la barra superior: sin conexión o con cambios pendientes muestra el número de cambios y abre el
 * diálogo de sincronización. Sin modo offline no se pinta.
 */
@Component({
  selector: 'offline-indicator',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, MatBadgeModule, MatTooltipModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (visible()) {
      <button
        mat-icon-button
        type="button"
        class="offline-indicator"
        [class.failed]="queue.failed()"
        [matBadge]="queue.pending() || null"
        [matBadgeHidden]="!queue.pending()"
        matBadgeSize="small"
        [matTooltip]="tooltip() | transloco: { count: queue.pending(), failed: queue.failed() }"
        [attr.aria-label]="tooltip() | transloco: { count: queue.pending(), failed: queue.failed() }"
        (click)="open()"
      >
        <mat-icon>{{ icon() }}</mat-icon>
      </button>
    }
  `,
  styles: [
    `
      /* Discreto: la mitad que un icon-button normal (24px en lugar de 48px) */
      :host {
        display: inline-flex;
        align-items: center;
        flex: none;
      }
      /* Sin nada que mostrar no ocupa sitio (ni el hueco del gap de la barra) */
      :host(:empty) {
        display: none;
      }
      .offline-indicator {
        --mat-icon-button-state-layer-size: 24px;
        --mat-icon-button-icon-size: 18px;
        --mat-icon-button-icon-color: var(--app-color-text-muted);

        mat-icon {
          font-size: 18px;
          width: 18px;
          height: 18px;
        }
      }
      .failed {
        --mat-icon-button-icon-color: var(--mat-sys-error);
      }
    `,
  ],
})
export class OfflineIndicatorComponent {
  readonly queue = inject(OfflineQueueService);
  private readonly dialog = inject(MatDialog);
  private readonly notify = inject(NotifyService);

  readonly visible = computed(() => this.queue.enabled() && (this.queue.pending() > 0 || !this.queue.online()));

  readonly icon = computed(() => {
    if (this.queue.syncState() === 'syncing') {
      return 'sync';
    }
    if (this.queue.failed()) {
      return 'sync_problem';
    }
    return this.queue.online() ? 'cloud_upload' : 'cloud_off';
  });

  readonly tooltip = computed(() => {
    if (this.queue.failed()) {
      return 'offline.indicator.failed';
    }
    return this.queue.online() ? 'offline.indicator.pending' : 'offline.indicator.offline';
  });

  constructor() {
    // Al volver la conexión con cambios pendientes, se avisa
    let wasOnline = this.queue.online();
    let notifiedAt = 0;
    effect(() => {
      const online = this.queue.online();
      const pending = untracked(this.queue.pending);
      // Tras un fallo de red se reintenta cada poco: el aviso, como mucho cada NOTIFY_EVERY
      const quiet = Date.now() - notifiedAt < NOTIFY_EVERY;
      if (online && !wasOnline && pending > 0 && !quiet && untracked(this.queue.syncState) !== 'syncing') {
        notifiedAt = Date.now();
        // Con subida automática se avisa de que se subirá sola si la conexión se mantiene
        const seconds = Math.round(untracked(this.queue.autoSyncDelay) / 1000);
        const key = seconds ? 'offline.notify.backOnlineAuto' : 'offline.notify.backOnline';
        this.notify.info(key, { count: pending, seconds });
      }
      wasOnline = online;
    });
  }

  open(): void {
    this.dialog.open(OfflineSyncDialogComponent, {
      width: '760px',
      maxWidth: '95vw',
      ariaLabelledBy: 'offline-sync-title',
    });
  }
}
